// Package api exposes the Grus controller over HTTP: REST under /v1 with an OpenAPI 3.1 document
// generated by huma. Requests are authenticated with a bearer token (the admin token or a
// per-instance token resolved by the controller). The package only calls controller.Service;
// it never changes state itself.
package api

import (
	"io"
	"log/slog"
	"net/http"
	"reflect"

	"github.com/danielgtaylor/huma/v2"
	"github.com/danielgtaylor/huma/v2/adapters/humago"

	"github.com/OneLiteFeatherNET/grus/internal/controller"
	"github.com/OneLiteFeatherNET/grus/internal/model"
	"github.com/OneLiteFeatherNET/grus/internal/templates"
)

// Config holds the settings of the HTTP API.
type Config struct {
	AdminToken     string // grants every scope except self; compared in constant time
	DebugEndpoints bool   // registers the admin-only debug routes
	Ready          func() bool
	Version        string
	// AgentTokens maps an agent host to the hex SHA-256 of its token. Empty disables agent tokens.
	AgentTokens map[string]string
	// Agents serves the /v1/agents and /v1/hosts routes. Nil answers them with 404.
	Agents Agents
}

const (
	// specVersion is the API version of the checked-in api/openapi.yaml.
	specVersion  = "1.0.0"
	apiTitle     = "Grus API"
	bearerScheme = "bearer"
)

// server holds the dependencies of the handlers. OpenAPI() builds a server without them: the
// handlers are registered for the document but never called.
type server struct {
	cfg    Config
	svc    controller.Service
	tpl    templates.Store
	events http.Handler
	log    *slog.Logger
	auth   *authenticator
}

// New returns the full HTTP handler. events is the SSE handler of the event hub (already writes the stream).
func New(cfg Config, svc controller.Service, tpl templates.Store, events http.Handler, logger *slog.Logger) http.Handler {
	if logger == nil {
		logger = slog.Default()
	}
	if events == nil {
		events = http.NotFoundHandler()
	}
	version := cfg.Version
	if version == "" {
		version = specVersion
	}
	mux := http.NewServeMux()
	s := newServer(cfg, svc, tpl, events, logger)
	api := build(mux, s, version)
	documentRaw(api.OpenAPI())
	s.registerRaw(mux)
	return mux
}

// OpenAPI returns the generated OpenAPI 3.1 document as YAML.
func OpenAPI() ([]byte, error) {
	s := newServer(Config{}, nil, nil, http.NotFoundHandler(), slog.New(slog.DiscardHandler))
	api := build(http.NewServeMux(), s, specVersion)
	documentRaw(api.OpenAPI())
	return api.OpenAPI().YAML()
}

func newServer(cfg Config, svc controller.Service, tpl templates.Store, events http.Handler, logger *slog.Logger) *server {
	return &server{
		cfg:    cfg,
		svc:    svc,
		tpl:    tpl,
		events: events,
		log:    logger,
		auth:   newAuthenticator(cfg.AdminToken, cfg.AgentTokens, svc, logger),
	}
}

// build registers every huma operation on mux and returns the huma API.
func build(mux *http.ServeMux, s *server, version string) huma.API {
	config := huma.DefaultConfig(apiTitle, version)
	config.DocsPath = ""
	config.OpenAPI.Components.SecuritySchemes = map[string]*huma.SecurityScheme{
		bearerScheme: {Type: "http", Scheme: "bearer"},
	}
	// model.Duration marshals as a Go duration string ("2m"), so its schema is a string.
	config.OpenAPI.Components.Schemas.RegisterTypeAlias(reflect.TypeFor[model.Duration](), reflect.TypeFor[string]())

	api := humago.New(mux, config)
	api.UseMiddleware(s.auth.middleware(api))
	s.registerPools(api)
	s.registerDeclarations(api)
	s.registerInstances(api)
	s.registerSelf(api)
	s.registerTemplates(api)
	s.registerAgents(api)
	if s.cfg.DebugEndpoints {
		s.registerDebug(api)
	}
	return api
}

// operation attaches the scope the middleware checks and the bearer security requirement.
func operation(scope string, op huma.Operation) huma.Operation {
	if op.Metadata == nil {
		op.Metadata = map[string]any{}
	}
	op.Metadata[metaScope] = scope
	op.Security = []map[string][]string{{bearerScheme: {}}}
	return op
}

// textBody streams r as text/plain and closes it when the response is written.
func textBody(r io.ReadCloser) *huma.StreamResponse {
	return &huma.StreamResponse{Body: func(hc huma.Context) {
		defer r.Close()
		hc.SetHeader("Content-Type", "text/plain; charset=utf-8")
		_, _ = io.Copy(hc.BodyWriter(), r)
	}}
}
